#include <bits/stdc++.h>
using namespace std;

vector<int> parent, sz;

int find(int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];   // 루트 찾기
    while (parent[x] != root) {                         // 경로 압축
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

bool unite(int a, int b) {             // union 은 C++ 예약어라 이름으로 못 써요
    a = find(a);
    b = find(b);
    if (a == b) return false;          // 이미 같은 그룹
    if (sz[a] < sz[b]) swap(a, b);
    parent[b] = a;                     // 작은 그룹을 큰 그룹 밑으로
    sz[a] += sz[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    parent.resize(n + 1);
    iota(parent.begin(), parent.end(), 0);
    sz.assign(n + 1, 1);
    while (q--) {
        char op;
        int a, b;
        cin >> op >> a >> b;
        if (op == 'U') unite(a, b);
        else cout << (find(a) == find(b) ? "YES" : "NO") << ' ' << sz[find(a)] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> parent;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   // 경로 절반 압축
        x = parent[x];
    }
    return x;
}

int main() {
    int n = 5;
    // {가중치, u, v} 로 두면 기본 sort 가 가중치 순으로 정렬해요
    vector<array<int, 3>> edges = {{3, 1, 2}, {1, 1, 3}, {7, 2, 3}, {5, 2, 4}, {2, 3, 4}, {4, 4, 5}, {6, 3, 5}};
    sort(edges.begin(), edges.end());

    parent.resize(n + 1);
    iota(parent.begin(), parent.end(), 0);
    long long total = 0;                 // 가중치 합은 long long
    vector<array<int, 3>> used;
    for (auto [w, u, v] : edges) {
        int ru = find(u), rv = find(v);
        if (ru != rv) {                  // 사이클이 생기지 않을 때만 고르기
            parent[ru] = rv;
            total += w;
            used.push_back({u, v, w});
        }
    }

    if ((int)used.size() == n - 1) {
        cout << total << '\n';
        for (auto [u, v, w] : used) cout << u << ' ' << v << ' ' << w << '\n';
    } else {
        cout << "연결되지 않음\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> parent;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main() {
    int n = 7;
    vector<pair<int, int>> edges = {{1, 2}, {2, 3}, {4, 5}, {5, 4}, {3, 1}};
    parent.resize(n + 1);
    iota(parent.begin(), parent.end(), 0);
    bool cycle = false;
    for (auto [a, b] : edges) {
        int ra = find(a), rb = find(b);
        if (ra == rb) cycle = true;      // 이미 연결된 두 정점을 또 이으면 사이클
        else parent[ra] = rb;
    }

    int components = 0;
    for (int v = 1; v <= n; v++)
        if (find(v) == v) components++;  // 루트의 개수 = 연결 요소 수
    cout << "연결 요소 " << components << '\n';
    cout << "사이클 " << (cycle ? "있음" : "없음") << '\n';
    return 0;
}

